    if (((step_1.orientToMovement > 0.5) && (active_1 > 0.5))) {
      vec4 previousMotion = readState(state, birthState, birthPass, address.rows, address.column, address.row);
      return vec4(geometry.x, geometry.y, geometry.z, movementRotation(previousMotion.z, previousMotion.w));
