    return vec4(motion.x, motion.y, 0.0, 0.0);
  }
  vec4 geometry = readState(state, birthState, birthPass, address.rows, address.column, (address.row + (address.rows * 4.0)));
  ParticleMotion particle = ParticleMotion(vec2(motion.x, motion.y), vec2(motion.z, motion.w), (age + step_1.seconds), lifetime, initialRotation, accumulatedRotation, angularVelocity, modifierVariation, geometry.z);
