}

vec4 integrate(sampler2D state, vec4 stepInput, vec4 emissionInput, vec4 shapeInput, vec4 shapeSpreadInput, vec4 appearanceInput, vec4 colorInput, vec4 motionSpreadInput, vec4 colorSpreadInput, vec4 geometrySpreadInput, vec4 positionInput, vec4 transformInput, vec4 orientationInput, sampler2D spawnMask, float rotationCurve, float angularVelocityCurve, float threadX, float threadY, float width, float rows, float capacity, sampler2D birthState, float birthPass) {
