  if (isSpawning) {
    ParticleBirth birth = ParticleBirth(stepInput[2], emissionInput[0], emissionInput[1], emissionInput[2], emissionInput[3], shapeInput[0], shapeInput[1], shapeInput[2], shapeSpreadInput[0], shapeSpreadInput[1], appearanceInput[0], appearanceInput[1], appearanceInput[2], appearanceInput[3], colorInput[0], colorInput[1], colorInput[2], colorInput[3], motionSpreadInput[0], motionSpreadInput[1], motionSpreadInput[2], motionSpreadInput[3], colorSpreadInput[0], colorSpreadInput[1], colorSpreadInput[2], colorSpreadInput[3], geometrySpreadInput[0], geometrySpreadInput[1], geometrySpreadInput[2], positionInput[0], positionInput[1], positionInput[2], positionInput[3], transformInput[0], transformInput[1], transformInput[2], transformInput[3], orientationInput[0], orientationInput[3]);
